package com.alibaba.asdp.core.stage.split;

import com.alibaba.asdp.api.trace.AsdpBizLogFactory;
import com.alibaba.asdp.api.trace.TracerCache;
import com.alibaba.asdp.common.diamond.CommonSettings;
import com.alibaba.asdp.common.log.LogSupplier;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.core.stage.split.invalidate.LogisticsInvalidator;
import com.alibaba.asdp.core.stage.split.splitter.DeliveryPackageSplitter;
import com.alibaba.asdp.sdk.constant.BetaTagsConstant;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.item.InvalidItem;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.model.product.DeliveryProduct;
import com.alibaba.asdp.sdk.model.session.DeliverySession;
import com.alibaba.asdp.sdk.support.ItemSupportUtils;
import com.alibaba.asdp.sdk.util.BetaTagsUtil;
import com.google.common.collect.Lists;
import lombok.Setter;
import org.apache.commons.collections4.CollectionUtils;
import org.slf4j.Logger;

import java.util.*;
import java.util.stream.Collectors;

import static com.alibaba.asdp.common.constant.InvalidItemReason.EXCEED_ITEM_LIMIT_INVALID_GIFT;

/**
 * 包裹拆单执行器
 * @author jiajun.njj 2020-02-05 21:48.
 */
public class PackageSplittersExecutor {

    private final Logger logger = AsdpBizLogFactory.getLogger("asdp-split");

    @Setter
    private List<DeliveryPackageSplitter> splitters;

    @Setter
    private List<LogisticsInvalidator> invalidate;

    private final GiftItemProcessor giftItemProcessor = new GiftItemProcessor();

    public void split(DeliverySession session) {
        // 识别betaTags，如果包含猫超闪购饿了么来源识别标，则跳过拆单逻辑
        if (CommonSettings.getInstance().openSkipMaochaoElemeSplitOrder()
            && BetaTagsUtil.containsSpecialBetaTag(session.getSourceEnvInfo(), BetaTagsConstant.MC_ELM_SOURCE)) {
            TracerCache.log("maochao fast buy eleme channel skip order split.", session.getSourceEnvInfo());
            return;
        }

        // 为赠品挂靠保留拆单前的交易订单结构
        Map<String, Set<String>> beforeSplitOrders = buildOrders(session.getDeliveryProducts());
        for (DeliveryPackageSplitter splitter : splitters) {
            if (SplitConfig.getInstance().canSplit(splitter.getClass().getSimpleName())) {
                splitter.split(session);
            } else {
                TracerCache.log("splitter is Closed.", splitter.getClass().getSimpleName());
            }
        }

        // 赠品挂靠
        giftItemProcessor.processGiftActivity(session, beforeSplitOrders);

        // 商品失效处理
        for (LogisticsInvalidator logisticsInvalidator : invalidate) {
            if (SplitConfig.getInstance().canInvalidate(logisticsInvalidator.getClass().getSimpleName())) {
                logisticsInvalidator.invalidate(session);
            } else {
                TracerCache.log("invalidator is Closed.", logisticsInvalidator.getClass().getSimpleName());
            }
        }

        if (SplitConfig.getInstance().isEnableDeliveryPackage50ItemLimitRevealSplitter()) {
            revealInvalidGiftItem(session);
        }
    }

    private void revealInvalidGiftItem(DeliverySession session) {
        if (session == null) {
            return;
        }
        List<DeliveryProduct> deliveryProducts = session.getDeliveryProducts();
        if (CollectionUtils.isEmpty(deliveryProducts)) {
            return;
        }

        List<InvalidItem> invalidItems = Lists.newArrayList();
        Iterator<DeliveryProduct> iterator = deliveryProducts.iterator();
        while (iterator.hasNext()) {
            DeliveryProduct deliveryProduct = iterator.next();
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            if (CollectionUtils.isEmpty(deliveryPackage.getItemInfos())) {
                iterator.remove();
                continue;
            }

            //如果一笔主单中主赠超过50个，失效掉赠品
            //这里不用管主品，因为主品在交易和asdp都定制了主品均衡拆分逻辑
            if (deliveryPackage.getItemInfos().size() > SplitConfig.getInstance().getDeliveryPackageItemLimit()) {
                List<AsdpItemInfo> needToRemoveGift = Lists.newLinkedList();
                List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
                Iterator<AsdpItemInfo> itemInfoIterator = itemInfos.iterator();
                while (itemInfoIterator.hasNext()) {
                    AsdpItemInfo itemInfo = itemInfoIterator.next();
                    boolean isGift = ItemSupportUtils.isGift(itemInfo);
                    if (isGift) {
                        needToRemoveGift.add(itemInfo);
                        itemInfoIterator.remove();
                    }
                }

                if (CollectionUtils.isEmpty(needToRemoveGift)) {
                    continue;
                }

                //失效多余赠品
                List<InvalidItem> tempInvalidItems = Lists.newArrayList();
                tempInvalidItems.addAll(needToRemoveGift
                        .stream()
                        .filter(ItemSupportUtils::isGift)
                        .map(
                                itemInfo -> {
                                    AsdpEcomItem ecomItem = itemInfo.getEcomItem();
                                    InvalidItem invalidItem = new InvalidItem();
                                    invalidItem.setItemUniqueKey(itemInfo.getUniqueKey());
                                    invalidItem.setItemId(ecomItem.getItemId());
                                    invalidItem.setSkuId(ecomItem.getSkuId());
                                    invalidItem.setUndeliverableReasonCode(EXCEED_ITEM_LIMIT_INVALID_GIFT.getCode());
                                    invalidItem.setUndeliverableReasonMessage(EXCEED_ITEM_LIMIT_INVALID_GIFT.getMsg());
                                    return invalidItem;
                                }
                        )
                        .collect(Collectors.toList()));

                if (CollectionUtils.isNotEmpty(tempInvalidItems)) {
                    invalidItems.addAll(tempInvalidItems);
                }

                if (itemInfos.size() == 0) {
                    iterator.remove();
                }

                logger.info("revealSplitInvalidGift#success");

                if (SplitConfig.getInstance().isEnableRevealSplitInvalidGiftLog()) {
                    logger.info("revealSplitInvalidGift.invalidGiftList={}", new LogSupplier(tempInvalidItems));
                }
            }
        }
        if (CollectionUtils.isNotEmpty(invalidItems)) {
            session.getInvalidItems().addAll(invalidItems);
        }
    }

    // key：商品uniqueKey、value：订单uniqueKeys
    private Map<String, Set<String>> buildOrders(List<DeliveryProduct> allDeliveryProducts) {
        Map<String, Set<String>> allOrdersUniqueKeys =  new HashMap<>();
        if (CollectionUtils.isEmpty(allDeliveryProducts)) {
            return allOrdersUniqueKeys;
        }

        for (DeliveryProduct deliveryProduct : allDeliveryProducts) {
            if (deliveryProduct.getDeliveryPackage() == null) {
                continue;
            }
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            if (CollectionUtils.isEmpty(deliveryPackage.getItemInfos())) {
                continue;
            }
            // 初始化订单的uniqueKeys
            Set<String> orderUniqueKeys = new HashSet<>();
            for (AsdpItemInfo asdpItemInfo : deliveryPackage.getItemInfos()) {
                if (asdpItemInfo == null || asdpItemInfo.getUniqueKey() == null) {
                    continue;
                }
                orderUniqueKeys.add(asdpItemInfo.getUniqueKey());
            }

            // 初始化商品uniqueKey和订单uniqueKeys的映射
            for(AsdpItemInfo asdpItemInfo : deliveryPackage.getItemInfos()) {
                if (asdpItemInfo == null || asdpItemInfo.getUniqueKey() == null) {
                    continue;
                }
                allOrdersUniqueKeys.put(asdpItemInfo.getUniqueKey(), orderUniqueKeys);
            }
        }
        return allOrdersUniqueKeys;
    }



}

