        Iterator<DeliveryProduct> iterator = deliveryProducts.iterator();
        while (iterator.hasNext()) {
            DeliveryProduct deliveryProduct = iterator.next();
            iterator.remove();
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            // 如果商品数量本身只有一个，不需要拆单
            if (deliveryPackage.getItemInfos().size() <= 1) {
                splitResult.add(deliveryProduct);
                continue;
            }
            ActivityInfo activityInfo = deliveryPackage.getItemInfos().get(0).getActivityInfo();
            if (null != activityInfo && null != activityInfo.getPreSaleActivityInfo()) {
                PreSaleActivityInfo preSaleActivityInfo = activityInfo.getPreSaleActivityInfo();
                // 预售尾款不需要拆单
                if (TradeStageConstant.FINAL_PAYMENT.equals(preSaleActivityInfo.getActivityStage())) {
                    splitResult.add(deliveryProduct);
                    continue;
                }
            }
            List<List<AsdpItemInfo>> itemLists = doSplit(deliveryPackage);
            // 如果拆完之后，商品列表只有一个，原结构返回
            if (itemLists.size() == 1) {
                splitResult.add(deliveryProduct);
                continue;
            }
            List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
			try {
				logger.warn(this.getClass().getName() + " split success, beforeItemIds={}, afterItemIds={}",
						itemInfos.stream()
								.map(AsdpItemInfo::getEcomItem)
								.map(item -> item.getItemId() + "_" + item.getSkuId())
								.collect(Collectors.toSet()),
						itemLists.stream()
								.map(items -> items.stream()
										.map(AsdpItemInfo::getEcomItem)
										.map(item -> item.getItemId() + "_" + item.getSkuId())
										.collect(Collectors.toList()))
								.collect(Collectors.toList()));
			} catch (Throwable ignore) {
                //日志失败忽略
			}
			TracerCache.log("split by:"+this.getClass().getName(), itemLists);
            AliMetricManager.getInstance().increase(SPLIT_METRIC_NAME, MapHelper.of(SPLIT_NAME_KEY,this.getClass().getSimpleName()));

            for (int index = 0; index < itemLists.size(); index++) {
                List<AsdpItemInfo> splitItemList = itemLists.get(index);
                DeliveryProduct productClone = deliveryProduct.clone(Joiner.on("_").join(deliveryPackage.getPackageId(), index));
                productClone.getDeliveryPackage().getItemInfos().clear();
                productClone.getDeliveryPackage().getItemInfos().addAll(splitItemList);
                splitResult.add(productClone);
            }
        }
        deliveryProducts.addAll(splitResult);
    }

    abstract List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage);

}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.LogisticsNode;
import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.Warehouse;
import com.alibaba.asdp.common.constant.AsdpStoreType;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * 按照仓类型拆单
 * @author jiajun.njj 2020/3/4 7:32 下午.
 */
public class WarehouseTypeSplitter extends AbsDeliveryPackageSplitter {

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_WAREHOUSE_TYPE_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_WAREHOUSE_TYPE_SPLITTER_CONFIG_KEY
//    )
    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        boolean canSplit = itemInfos.stream().anyMatch(itemInfo -> {
            Set<Integer> itemTags = itemInfo.getEcomItem().getItemTags();
            return CollectionUtils.containsAny(itemTags, SplitConfig.getInstance().getWarehouseTypeSplitTags());
        });

        if (!canSplit) {
            splitItemLists.add(itemInfos);
            return splitItemLists;
        }

        Map<Boolean, List<AsdpItemInfo>> splitItemsMap =  itemInfos.stream().collect(Collectors.groupingBy(item -> {
                String storeType = getStoreType(item.getFromNode());
                return AsdpStoreType.STORE.getCode().toString().equals(storeType);
            }
        ));
        splitItemLists.addAll(splitItemsMap.values());
        return splitItemLists;
    }

    private String getStoreType(LogisticsNode fromNode) {
        if (null == fromNode) {
            return null;
        }
        if (fromNode instanceof Warehouse) {
            Warehouse warehouse = (Warehouse)fromNode;
            return warehouse.getStoreType();
        }
        return null;
    }

}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.Shop;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;

import java.util.List;
import java.util.Map;

/**
 * 门店拆单
 * 和仓拆单的区别是需要识别发货地类型是门店
 * @author jiajun.njj 2020/3/11 3:09 下午.
 */
public class ShopSplitter extends AbsDeliveryPackageSplitter {

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_SHOP_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_SHOP_SPLITTER_CONFIG_KEY
//    )
    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        if (CollectionUtils.isEmpty(SplitConfig.getInstance().getShopSplitTags())
            && CollectionUtils.isEmpty(SplitConfig.getInstance().getShopSplitSellers())) {
            splitItemLists.add(itemInfos);
            return splitItemLists;
        }

        List<AsdpItemInfo> noShopItemList = Lists.newArrayList();
        Map<String, List<AsdpItemInfo>> shopItemGroups = Maps.newHashMap();
        for (AsdpItemInfo itemInfo : itemInfos) {
            if (itemInfo.getFromNode() == null || !Shop.TYPE.equals(itemInfo.getFromNode().getType())) {
                noShopItemList.add(itemInfo);
                continue;
            }
            AsdpEcomItem ecomItem = itemInfo.getEcomItem();
            if (CollectionUtils.containsAny(SplitConfig.getInstance().getShopSplitTags(), ecomItem.getItemTags())
                || SplitConfig.getInstance().getShopSplitSellers().contains(ecomItem.getSeller().getUserId())) {
                shopItemGroups.computeIfAbsent(ecomItem.getSeller().getUserId()+itemInfo.getFromNode().getCode(), (key)->Lists.newArrayList()).add(itemInfo);
            } else {
                noShopItemList.add(itemInfo);
            }
        }
        if (MapUtils.isNotEmpty(shopItemGroups)) {
            splitItemLists.addAll(shopItemGroups.values());
        }
        if (CollectionUtils.isNotEmpty(noShopItemList)) {
            splitItemLists.add(noShopItemList);
        }
        return splitItemLists;
    }
}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.core.constant.SplitterConstants;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.inventory.AsdpInventory;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.support.ItemSupportUtils;
import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * 供应商拆单
 * c2m按供应商拆单，但c2m依旧是一品一供的模式，按供应商拆单本身是个伪命题
 *
 * 一盘货是多供应商模式，最初在猫超进行试点，设计方案中仅考虑了猫超单个场景，所以拆单仅根据是否一盘货属性拆单
 * 但是本质上也是按照供应商拆单，后续如果有一品多供的场景，也是往按供应商拆单的方向走
 *
 * @author jiajun.njj 2020/7/24 4:40 下午
 */
public class SupplierSplitter extends AbsDeliveryPackageSplitter {

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_SUPPLIER_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_SUPPLIER_SPLITTER_CONFIG_KEY
//    )
    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {


        ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();

        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        if (org.apache.commons.collections4.CollectionUtils.isEmpty(itemInfos)){
            return result;
        }
        //是否需要拆单
        if (!needSplit(itemInfos)){
            result.add(itemInfos);
            return result;
        }

        return split(itemInfos);

    }


    private boolean needSplit(List<AsdpItemInfo> itemInfos) {

        if (org.apache.commons.collections4.CollectionUtils.isEmpty(itemInfos)){
            return false;
        }

        try {
            //记录主品
            List<AsdpItemInfo> mainItems = Lists.newArrayList();
            //是否带了拆单屏蔽标
            boolean haveBlackTag = false;

            for (AsdpItemInfo itemInfo : itemInfos) {
                //判断商品上面是否有屏蔽标
                if (org.apache.commons.collections4.CollectionUtils.containsAny(itemInfo.getEcomItem().getItemTags(),
                        SplitConfig.getInstance().getGiftOneStockSplitterBlackTags())) {
                    haveBlackTag = true;
                }

                //是不是赠品
                boolean isGift = ItemSupportUtils.isGift(itemInfo);
                if (isGift) {
                    continue;
                }
                mainItems.add(itemInfo);
            }

            if (!haveBlackTag){
                //没有黑标
                return true;
            }

            //主品拆单
            List<List<AsdpItemInfo>> split = this.split(mainItems);
            if (split.size() <= SplitterConstants.SPLIT_MIN_SIZE){
                //主品未拆单，并且有主赠拆单屏蔽标
                return false;
            }
        }catch (Exception e){
            return true;
        }
        return true;
    }

    private List<List<AsdpItemInfo>> split(List<AsdpItemInfo> itemInfos) {

        if (org.apache.commons.collections.CollectionUtils.isEmpty(itemInfos)) {
            return Lists.newArrayList();
        }

        try {
            List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
            Map<String, List<AsdpItemInfo>> splitItemsMap = itemInfos.stream().collect(Collectors.groupingBy(this::getSupplierId));
            splitItemLists.addAll(splitItemsMap.values());
            return splitItemLists;
        } catch (Exception e) {
            logger.error("SupplierSplitter.split error message:" + e.getMessage(), e);
            ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();
            result.add(itemInfos);
            return result;
        }
    }

    private String getSupplierId(AsdpItemInfo itemInfo) {
        AsdpInventory inventory = itemInfo.getInventory();
        // 这个是一盘货的拆单逻辑，本质上是按照供应商拆单，这里把它当供应商用
        if (inventory != null) {
            String oneStockOrder = MapUtils.getString(inventory.getVerticalAttribute(), "one-stock-order");
            if ("1".equals(oneStockOrder)) {
                return "virtualSupplier";
            }
        }

        if (CollectionUtils.containsAny(itemInfo.getEcomItem().getItemTags(), SplitConfig.getInstance().getSupplierSplitTags())) {
            return MapUtils.getString(itemInfo.getEcomItem().getFeature(), "supplier_id", "0");
        }
        return "0";
    }
}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.api.trace.AsdpBizLogFactory;
import com.alibaba.asdp.api.trace.TracerCache;
import com.alibaba.asdp.common.metrics.AliMetricManager;
import com.alibaba.asdp.common.util.MapHelper;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.item.AsdpScItem;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.model.product.DeliveryProduct;
import com.alibaba.asdp.sdk.model.session.DeliverySession;
import com.google.common.base.Joiner;
import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;

import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * 货品拆单
 */
public class ScItemSplitter implements DeliveryPackageSplitter{
    Logger logger = AsdpBizLogFactory.getLogger("asdp-split");


    private static final String DONT_NEED_SPLIT = "DONT_NEED_SPLIT";

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_SCITEM_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_SCITEM_SPLITTER_CONFIG_KEY
//    )
    @Override
    public void split(DeliverySession session) {
        List<DeliveryProduct> deliveryProducts = session.getDeliveryProducts();
        List<DeliveryProduct> splitResult = Lists.newArrayList();
        Iterator<DeliveryProduct> iterator = deliveryProducts.iterator();
        while (iterator.hasNext()) {
            DeliveryProduct deliveryProduct = iterator.next();
            iterator.remove();
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            // 如果商品数量本身只有一个，不需要拆单
            if(CollectionUtils.isEmpty(deliveryPackage.getItemInfos())){
                continue;
            }
            if (deliveryPackage.getItemInfos().size() <= 1) {
                splitResult.add(deliveryProduct);
                continue;
            }
            List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
            List<List<AsdpItemInfo>> itemLists = splitByFeature(itemInfos);
            // 如果拆完之后，商品列表只有一个，原结构返回
            if (itemLists.size() == 1) {
                splitResult.add(deliveryProduct);
                continue;
            }
            logger.warn(this.getClass().getName()+" split success, itemIds={}", itemInfos.stream().map(AsdpItemInfo::getUniqueKey).collect(Collectors.toSet()));
            TracerCache.log("split by:"+this.getClass().getName(), itemLists);
            AliMetricManager.getInstance().increase(SPLIT_METRIC_NAME, MapHelper.of(SPLIT_NAME_KEY,this.getClass().getSimpleName()));

            for (int index = 0; index < itemLists.size(); index++) {
                List<AsdpItemInfo> splitItemList = itemLists.get(index);
                DeliveryProduct productClone = deliveryProduct.clone(Joiner.on("_").join(deliveryPackage.getPackageId(), index));
                productClone.getDeliveryPackage().getItemInfos().clear();
                productClone.getDeliveryPackage().getItemInfos().addAll(splitItemList);
                splitResult.add(productClone);
            }
        }
        deliveryProducts.addAll(splitResult);
    }


    private List<List<AsdpItemInfo>> splitByFeature(List<AsdpItemInfo> itemInfos){
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();

        boolean canSplit = false;
        for (AsdpItemInfo itemInfo : itemInfos) {
            if(null == itemInfo){
                continue;
            }
            AsdpEcomItem ecomItem = itemInfo.getEcomItem();
            if(null == ecomItem){
                continue;
            }
            Set<Integer> itemTags = ecomItem.getItemTags();
            if(CollectionUtils.containsAny(SplitConfig.getInstance().getItemTagsOfScItemFeatureSplitItemTags(),itemTags)){
                canSplit = true;
                break;
            }
        }

        if (!canSplit) {
            splitItemLists.add(itemInfos);
            return splitItemLists;
        }

        Map<String, List<AsdpItemInfo>> collect = itemInfos.stream().collect(Collectors.groupingBy(itemInfo -> {
            AsdpScItem scItem = itemInfo.getScItem();
            if(null == scItem){
                return DONT_NEED_SPLIT;
            }
            Map<String, String> scItemFeatures = scItem.getScItemFeatures();
            if(MapUtils.isEmpty(scItemFeatures)){
                return DONT_NEED_SPLIT;
            }
            for (Map.Entry<String, String> entry : scItemFeatures.entrySet()) {

                if(SplitConfig.getInstance().getKeyOfScItemFeatureSplitKey().contains(entry.getKey())){
                    //value会不会是空啊
                    if(StringUtils.isNotBlank(entry.getValue())){
                        return entry.getValue();
                    }
                    return DONT_NEED_SPLIT;
                }
            }

            return DONT_NEED_SPLIT;
        }));
        splitItemLists.addAll(collect.values());
        return splitItemLists;
    }
}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.api.trace.AsdpBizLogFactory;
import com.alibaba.asdp.core.constant.SplitterConstants;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.inventory.AsdpInventory;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.support.ItemSupportUtils;
import com.google.common.collect.Lists;
import org.apache.commons.collections.CollectionUtils;
import org.apache.commons.collections.MapUtils;
import org.slf4j.Logger;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * 一盘货拆单
 *
 * @author Qingheng
 * @date 2022/8/15
 */
public class OneStockSplitter extends AbsDeliveryPackageSplitter {


    private static final Logger logger = AsdpBizLogFactory.getLogger("OneStockSplitter");

    private static final String ONE_STOCK = "ONE_STOCK";

    private static final String DONT_NEED_SPLIT = "DONT_NEED_SPLIT";

    private static final String ONE_STOCK_ORDER = "one-stock-order";

    private static final String ONE_STOCKK_ORDER_VALUE = "1";


//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_ONE_STOCK_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_ONE_STOCK_SPLITTER_CONFIG_KEY
//    )
    @Override
    List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {

        ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();

        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        if (org.apache.commons.collections4.CollectionUtils.isEmpty(itemInfos)) {
            return result;
        }
        //是否需要拆单
        if (!needSplit(itemInfos)) {
            result.add(itemInfos);
            return result;
        }

        return split(itemInfos);
    }

    private boolean needSplit(List<AsdpItemInfo> itemInfos) {

        if (org.apache.commons.collections4.CollectionUtils.isEmpty(itemInfos)) {
            return false;
        }

        try {
            //记录主品
            List<AsdpItemInfo> mainItems = Lists.newArrayList();
            //是否带了拆单屏蔽标
            boolean haveBlackTag = false;

            for (AsdpItemInfo itemInfo : itemInfos) {
                //判断商品上面是否有屏蔽标
                if (org.apache.commons.collections4.CollectionUtils.containsAny(itemInfo.getEcomItem().getItemTags(),
                        SplitConfig.getInstance().getGiftOneStockSplitterBlackTags())) {
                    haveBlackTag = true;
                }

                //是不是赠品
                boolean isGift = ItemSupportUtils.isGift(itemInfo);
                if (isGift) {
                    continue;
                }
                mainItems.add(itemInfo);
            }

            if (!haveBlackTag) {
                //没有黑标
                return true;
            }

            //主品拆单
            List<List<AsdpItemInfo>> split = this.split(mainItems);
            if (split.size() <= SplitterConstants.SPLIT_MIN_SIZE) {
                //主品未拆单，并且有主赠拆单屏蔽标
                return false;
            }
        } catch (Exception e) {
            return true;
        }
        return true;
    }

    private List<List<AsdpItemInfo>> split(List<AsdpItemInfo> itemInfos) {

        if (CollectionUtils.isEmpty(itemInfos)) {
            return Lists.newArrayList();
        }

        try {
            Map<String, List<AsdpItemInfo>> collect = itemInfos.stream().collect(Collectors.groupingBy(itemInfo -> {
                AsdpInventory asdpInventory = itemInfo.getInventory();
                if (asdpInventory == null) {
                    return DONT_NEED_SPLIT;
                }

                if (itemInfo.getEcomItem() == null || itemInfo.getEcomItem().getItemTags() == null) {
                    return DONT_NEED_SPLIT;
                }

                // 商品标按一盘货拆单配置
                if (SplitConfig.getInstance().getOneStockSplitByItemTags() && CollectionUtils.containsAny(itemInfo.getEcomItem().getItemTags(), SplitConfig.getInstance().getOneStockSplitTags())) {
                    String oneStockOrder = MapUtils.getString(asdpInventory.getVerticalAttribute(), ONE_STOCK_ORDER);
                    if (ONE_STOCKK_ORDER_VALUE.equals(oneStockOrder)) {
                        return ONE_STOCK;
                    }
                }
                return DONT_NEED_SPLIT;
            }));
            return Lists.newArrayList(collect.values());
        } catch (Exception e) {
            logger.error("OneStockSplitter.split error message:" + e.getMessage(), e);
            ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();
            result.add(itemInfos);
            return result;
        }

    }
}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.support.ItemSupportUtils;
import com.alibaba.delivery.common.diamond.AdpNewLogisticBizConfig;
import com.google.common.collect.Lists;
import com.google.common.collect.Sets;
import org.apache.commons.collections4.CollectionUtils;

import java.util.*;
import java.util.stream.Collectors;

/**
 * 发货模式拆单，目前仅识别菜鸟非菜鸟两种发货模式
 * 这里是从原本sdp的小电强控拆单、母婴强控拆单、仓盟小电&快消强控拆单迁移上来的逻辑，逻辑有做改造合并，与原有逻辑并不完全一致；
 *
 * 原本逻辑是：
 * 1. 小电菜鸟强控与非强控分别拆成两单；
 * 2. 母婴菜鸟强控与非强控分别拆成两单；【这里原本母婴强控的识别规则是同时有181889(商家标)和1493634(商品标)的视为强控，否则视为非强控，这里逻辑其实有修改，变成了仅识别商品标】
 * 3. 仓盟菜鸟强控与非强控分别拆成两单，但仓盟强控包含仓盟小电类目强控和仓盟快消类目强控，这两个强控类目自身不拆单
 *
 * 由上面第三个拆单逻辑可以看出来，不同的菜鸟强控类别之间本身是不需要拆单的，只是因为原来三个拆单业务没有交集，所以分开写实现的业务结果是一样的，但其实这里拆单只需要区分菜鸟强控与非强控即可，不需要区分是哪种类型的菜鸟强控
 *
 * 于是这里的拆单逻辑写得比较简单
 *
 * @author jiajun.njj 2020/3/4 5:05 下午.
 */
public class ConsignModelSplitter extends AbsDeliveryPackageSplitter {


    private static final int SPLIT_MIN_SIZE = 1;

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_CONSIGN_MODEL_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_CONSIGN_MODEL_SPLITTER_CONFIG_KEY
//    )
    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        if (!needSplitByTag(itemInfos)) {
            ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();
            result.add(itemInfos);
           return result;
        }
        return split(itemInfos);
    }

    private List<List<AsdpItemInfo>> split(List<AsdpItemInfo> itemInfos) {
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        splitItemLists.add(itemInfos);
        for (Integer tag : SplitConfig.getInstance().getSplitTags()) {
            splitItemLists = doSplitByTag(splitItemLists, tag);
        }
        splitItemLists = doSplitByShipper(splitItemLists);
        return splitItemLists;
    }

    private boolean needSplitByTag(List<AsdpItemInfo> itemInfos) {

        if (CollectionUtils.isEmpty(itemInfos)){
            return false;
        }

        try {
            //记录主品
            List<AsdpItemInfo> mainItems = Lists.newArrayList();
            //是否带了主赠按仓拆单屏蔽标
            boolean haveBlackTag = false;

            for (AsdpItemInfo itemInfo : itemInfos) {
                //判断商品上面是否有屏蔽标
                if (CollectionUtils.containsAny(itemInfo.getEcomItem().getItemTags(),
                        AdpNewLogisticBizConfig.giftItemTagSplitBlackTags)) {
                    haveBlackTag = true;
                }

                //是不是赠品
                boolean isGift = ItemSupportUtils.isGift(itemInfo);
                if (isGift) {
                    continue;
                }
                mainItems.add(itemInfo);
            }

            if (!haveBlackTag){
                //没有黑标
                return true;
            }

            //主品拆单
            List<List<AsdpItemInfo>> split = this.split(mainItems);
            if (split.size() == SPLIT_MIN_SIZE){
                //主品未拆单，并且有主赠拆单屏蔽标
                return false;
            }
        }catch (Exception e){
            return true;
        }
        return true;
    }

    /**
     * 这个是猫超的按商品标拆单
     */
    private List<List<AsdpItemInfo>> doSplitByTag(List<List<AsdpItemInfo>> itemLists, Integer tag) {
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        for (List<AsdpItemInfo> itemInfos : itemLists) {
            if (itemInfos.size() <= 1) {
                splitItemLists.add(itemInfos);
                continue;
            }
            Map<Boolean, List<AsdpItemInfo>> splitItemsMap =  itemInfos.stream().collect(Collectors.groupingBy(item -> {
                        Set<Integer> itemTags = item.getEcomItem().getItemTags();
                        if (CollectionUtils.isEmpty(itemTags)) {
                            return false;
                        }
                        return itemTags.contains(tag);
                    }
            ));
            splitItemLists.addAll(splitItemsMap.values());
        }
        return splitItemLists;
    }

    /**
     * 这个是按发货方拆单
     */
    private List<List<AsdpItemInfo>> doSplitByShipper(List<List<AsdpItemInfo>> itemLists) {
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        for (List<AsdpItemInfo> itemInfos : itemLists) {
            if (itemInfos.size() <= 1) {
                splitItemLists.add(itemInfos);
                continue;
            }
            Map<Boolean, List<AsdpItemInfo>> splitItemsMap =  itemInfos.stream().collect(Collectors.groupingBy(this::isCnShipper));
            splitItemLists.addAll(splitItemsMap.values());
        }
        return splitItemLists;
    }

    /**
     * 是否菜鸟发货
     */
    private boolean isCnShipper(AsdpItemInfo asdpItemInfo) {
        AsdpEcomItem ecomItem = asdpItemInfo.getEcomItem();
        return CollectionUtils.containsAny(ecomItem.getItemTags(), SplitConfig.getInstance().getCnShipperTags());
    }

}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.core.diamond.SplitConfig;
