import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;
import org.apache.commons.lang3.StringUtils;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * 按业务身份拆单
 * 这里就按照国内段身份拆单
 * @author jiajun.njj 2020/3/4 8:50 下午.
 */
public class LogisticsIdentitySplitter extends AbsDeliveryPackageSplitter {

    public static final String DONT_NEED_SPLIT = "DONT_NEED_SPLIT";

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_LOGISTICS_IDENTITY_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_LOGISTICS_IDENTITY_SPLITTER_CONFIG_KEY
//    )
    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
        List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
        Map<String, List<AsdpItemInfo>> splitItemLists = itemInfos.stream().collect(Collectors.groupingBy(itemInfo -> {
            AsdpIdentity identity = itemInfo.getIdentity();
            LogisticsIdentity logisticsIdentity = identity.getLogisticsIdentity();
            String inlandBizCode = logisticsIdentity.getInlandBizCode();
            // 这里的业务身份不与任何业务身份做拆单
            if (SplitConfig.getInstance().getNotNeedSplitIdentities().contains(logisticsIdentity.getInlandBizCode())) {
                return DONT_NEED_SPLIT;
            }
            // 这里的业务身份按照拆单key做拆单
            String splitKey = SplitConfig.getInstance().getIdentitySplitKey().get(inlandBizCode);
            if (StringUtils.isNotBlank(splitKey)) {
                return splitKey;
            }
            return inlandBizCode;
        }));

        List<List<AsdpItemInfo>> splitResult = Lists.newArrayList();
        List<AsdpItemInfo> dontNeetSplitGroup = splitItemLists.remove(DONT_NEED_SPLIT);
        if (MapUtils.isEmpty(splitItemLists)) {
            splitResult.add(dontNeetSplitGroup);
        } else {
            splitResult.addAll(splitItemLists.values());
            if (CollectionUtils.isNotEmpty(dontNeetSplitGroup)) {
                splitResult.get(0).addAll(dontNeetSplitGroup);
            }
        }

        return splitResult;
    }

}

