import com.alibaba.asdp.api.trace.TracerCache;
import com.alibaba.asdp.common.constant.AdapterConstant;
import com.alibaba.asdp.common.constant.SerializeConstant;
import com.alibaba.asdp.common.metrics.AliMetricManager;
import com.alibaba.asdp.common.util.MapHelper;
import com.alibaba.asdp.core.ApplicationContextHolder;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.model.product.DeliveryProduct;
import com.alibaba.asdp.sdk.model.protocol.DeliveryProtocolClause;
import com.alibaba.asdp.sdk.model.session.DeliverySession;
import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.JSONObject;
import com.alibaba.fastjson.TypeReference;
import com.alibaba.fastjson.serializer.SerializerFeature;
import com.cainiao.sdp.shared.api.service.model.response.outbound.promiseservice.WdkTimeSlicePromiseService;
import com.google.common.base.Joiner;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.wdk.fulfillpromise.model.FulfillResult;
import com.wdk.fulfillpromise.model.promise.FulfillProduct;
import com.wdk.fulfillpromise.model.promise.FulfillProductGroup;
import com.wdk.fulfillpromise.model.split.SplitOption;
import com.wdk.fulfillpromise.split.api.FulfillSplitOrderServiceClient;
import com.wdk.infrastructure.client.enums.ChannelSourceType;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.Logger;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import static com.alibaba.delivery.common.constant.ServiceCodeConstant.SERVICE_CODE__WDK_TIME_SLICE;

/**
 * 共享库存时间片拆单
 * @author jiajun.njj 2020/9/9 20:08 下午
 */
public class WdkSplitter implements DeliveryPackageSplitter {

    private final Logger logger = AsdpBizLogFactory.getLogger("asdp-split");

    protected boolean needSplit(DeliveryPackage deliveryPackage) {
        if (CollectionUtils.isEmpty(deliveryPackage.getItemInfos())) {
            return false;
        }
        AsdpItemInfo asdpItemInfo = deliveryPackage.getItemInfos().get(0);
        FulfillProduct wdkPromiseService = getWdkPromiseService(asdpItemInfo);
        return wdkPromiseService != null;
    }

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_WDK_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_WDK_SPLITTER_CONFIG_KEY
//    )
    public List<List<AsdpItemInfo>> doSplit(DeliveryProduct deliveryProduct) {
        DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
        List<List<AsdpItemInfo>> splitItemLists = Lists.newArrayList();
        Map<FulfillProduct, AsdpItemInfo> hasPromiseItemMap = Maps.newHashMap();
        for (AsdpItemInfo itemInfo : deliveryPackage.getItemInfos()) {
            if (itemInfo == null) {
                continue;
            }
            FulfillProduct wdkPromiseService = getWdkPromiseService(itemInfo);
            if (wdkPromiseService == null) {
                continue;
            }
            hasPromiseItemMap.put(wdkPromiseService, itemInfo);
        }
        SplitOption splitOption = new SplitOption();
        splitOption.setChannelSourceType(ChannelSourceType.TC.getValue().intValue());
        FulfillSplitOrderServiceClient fulfillSplitOrderServiceClient = ApplicationContextHolder.get().getBean(FulfillSplitOrderServiceClient.class);
        ArrayList<FulfillProduct> fulfillProducts = Lists.newArrayList(hasPromiseItemMap.keySet());
        FulfillResult<List<FulfillProductGroup>> wdkResult = fulfillSplitOrderServiceClient.split(fulfillProducts, splitOption);
        if (!wdkResult.isSuccess()) {
            splitItemLists.add(deliveryPackage.getItemInfos());
            return splitItemLists;
        }
        List<FulfillProductGroup> fulfillProductGroups = wdkResult.getModel();
        for (FulfillProductGroup fulfillProductGroup : fulfillProductGroups) {
            List<FulfillProduct> groupFulfillProducts = fulfillProductGroup.getFulfillProductList();
            List<AsdpItemInfo> itemInfos = Lists.newArrayList();
            for (FulfillProduct fulfillProduct : groupFulfillProducts) {
                AsdpItemInfo asdpItemInfo = hasPromiseItemMap.get(fulfillProduct);
                itemInfos.add(asdpItemInfo);
            }
            List<DeliveryProtocolClause> expectProtocols = deliveryProduct.getExpectProtocols();
            String wdkFulfillProductGroup = JSON.toJSONString(fulfillProductGroup, SerializerFeature.DisableCircularReferenceDetect);
            if (StringUtils.isNotBlank(wdkFulfillProductGroup)) {
                Map<String, String> extend = Maps.newHashMap();
                extend.put(AdapterConstant.WDK_FULFIL_PRODUCT_GROUP, wdkFulfillProductGroup);
                DeliveryProtocolClause wdkProtocol = new DeliveryProtocolClause();
                wdkProtocol.setProtocolType(SerializeConstant.PROTOCOL_TYPE_WDK);
                wdkProtocol.setTags(extend);
                expectProtocols.add(wdkProtocol);
            }
            splitItemLists.add(itemInfos);
        }
        return splitItemLists;
    }

    private FulfillProduct getWdkPromiseService(AsdpItemInfo itemInfo) {
        try {
            LogisticsNode fromNode = itemInfo.getFromNode();
            if (!(fromNode instanceof Shop)) {
                return null;
            }
            Shop shop = (Shop)fromNode;
            String promiseServices = shop.getAttributes().get(AdapterConstant.OUTBOUND_SOLUTION);
            if (StringUtils.isBlank(promiseServices)) {
                return null;
            }
            Map<String, JSONObject> promiseServiceMap = JSON.parseObject(promiseServices, new TypeReference<Map<String, JSONObject>>() {});
            JSONObject wdkPromiseServiceJson = promiseServiceMap.get(SERVICE_CODE__WDK_TIME_SLICE);
            if (wdkPromiseServiceJson == null) {
                return null;
            }

            WdkTimeSlicePromiseService wdkPromiseService = JSON.toJavaObject(wdkPromiseServiceJson, WdkTimeSlicePromiseService.class);
            String fulfillProductString = MapUtils.getString(wdkPromiseService.getFeatures(), "fulfillProduct");
            if (fulfillProductString == null) {
                return null;
            }
            FulfillProduct fulfillProduct = JSON.parseObject(fulfillProductString, FulfillProduct.class);
            fulfillProduct.setOutId(itemInfo.getUniqueKey());
            return fulfillProduct;
        } catch (Exception e) {
            logger.error("getWdkPromiseService error", e);
        }
        return null;
    }

    @Override
    public void split(DeliverySession session) {
        List<DeliveryProduct> deliveryProducts = session.getDeliveryProducts();
        List<DeliveryProduct> splitResult = Lists.newArrayList();
        Iterator<DeliveryProduct> iterator = deliveryProducts.iterator();
        while (iterator.hasNext()) {
            DeliveryProduct deliveryProduct = iterator.next();
            iterator.remove();
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            if ( !needSplit(deliveryPackage) ) {
                splitResult.add(deliveryProduct);
                continue;
            }
            List<List<AsdpItemInfo>> itemLists = doSplit(deliveryProduct);
            // 如果拆完之后，商品列表只有一个，原结构返回
            if (itemLists.size() == 1) {
                splitResult.add(deliveryProduct);
                continue;
            }
            List<AsdpItemInfo> itemInfos = deliveryPackage.getItemInfos();
            logger.warn(this.getClass().getName()+" split success, itemIds={}", itemInfos.stream().map(AsdpItemInfo::getUniqueKey).collect(Collectors.toSet()));
            TracerCache.log("split by:"+this.getClass().getName(), itemLists);
            AliMetricManager.getInstance().increase(SPLIT_METRIC_NAME, MapHelper.of(SPLIT_NAME_KEY,this.getClass().getSimpleName()));

            for (int index = 0; index < itemLists.size(); index++) {
                List<AsdpItemInfo> splitItemList = itemLists.get(index);
                DeliveryProduct productClone = deliveryProduct.clone(Joiner.on("_").join(deliveryPackage.getPackageId(), index));
                productClone.getDeliveryPackage().getItemInfos().clear();
                productClone.getDeliveryPackage().getItemInfos().addAll(splitItemList);
                splitResult.add(productClone);
            }
        }
        deliveryProducts.addAll(splitResult);
    }
}

