package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.LogisticsNode;
import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.Shop;
import com.alibaba.asdp.adapter.adp.AdpRequestConverter;
import com.alibaba.asdp.common.constant.AdapterConstant;
import com.alibaba.asdp.common.constant.SerializeConstant;
import com.alibaba.asdp.common.constant.TradeStageConstant;
import com.alibaba.asdp.core.util.ItemUtils;
import com.alibaba.asdp.sdk.BizServiceLocator;
import com.alibaba.asdp.sdk.model.activity.ActivityInfo;
import com.alibaba.asdp.sdk.model.activity.PreSaleActivityInfo;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.item.InvalidItem;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.model.product.DeliveryProduct;
import com.alibaba.asdp.sdk.model.protocol.DeliveryProtocolClause;
import com.alibaba.asdp.sdk.model.session.DeliverySession;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.taobao.delivery.common.constant.ServiceErrorCode;
import com.taobao.delivery.common.dataobject.trade.ItemPackageTO;
import com.taobao.delivery.common.dataobject.trade.ItemSplitGroup;
import com.taobao.delivery.common.dataobject.trade.OrderSplitQueryTO;
import com.taobao.delivery.common.dataobject.trade.OrderSplitResultTO;
import com.taobao.delivery.common.transfer.DeliveryResult;
import com.taobao.delivery.common.transfer.ItemDesc;
import com.taobao.delivery.common.util.AppClientInfo;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;
import org.apache.commons.lang3.StringUtils;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * @author jiajun.njj 2020/8/4 10:12 下午
 */
public class AdpSplitter implements DeliveryPackageSplitter {

//    @RecordLog(
//            name = AsdpDefenderConstant.ASDP_L2_ADP_SPLITTER,
//            externalConfigNamespace = AdpBizAbilityConstant.ADP_PLATFORM_METRIC_CONFIG_NAMESPACE,
//            externalConfigKey = AsdpDefenderConstant.ASDP_L2_ADP_SPLITTER_CONFIG_KEY
//    )
    @Override
    public void split(DeliverySession session) {
        List<DeliveryProduct> deliveryProducts = session.getDeliveryProducts().stream().filter(product -> {
            // 只有一个商品的订单不需要拆单
            List<AsdpItemInfo> itemInfos = product.getDeliveryPackage().getItemInfos();

            // 这个共享库存拆单，在拆单链路透内容了，必须得调
            AsdpItemInfo asdpItemInfo = itemInfos.get(0);
            if (asdpItemInfo != null) {
                LogisticsNode fromNode = asdpItemInfo.getFromNode();
                if (fromNode instanceof Shop) {
                    Shop shop = (Shop)fromNode;
                    if (shop.getAttributes().containsKey(AdapterConstant.OUTBOUND_SOLUTION)) {
                        return true;
                    }
                }
            }
            if (CollectionUtils.isEmpty(itemInfos) || itemInfos.size() <= 1) {
                return false;
            }

            //猫享不走adp拆单
            if (ItemUtils.isFcOfficialItem(itemInfos)) {
                return false;
            }

            ActivityInfo activityInfo = itemInfos.get(0).getActivityInfo();
            if (null != activityInfo && null != activityInfo.getPreSaleActivityInfo()) {
                PreSaleActivityInfo preSaleActivityInfo = activityInfo.getPreSaleActivityInfo();
                // 预售尾款不需要拆单
                return !TradeStageConstant.FINAL_PAYMENT.equals(preSaleActivityInfo.getActivityStage());
            }
            return true;
        }).collect(Collectors.toList());
        if (CollectionUtils.isEmpty(deliveryProducts)) {
            return;
        }

        OrderSplitQueryTO orderSplitQueryTO = AdpRequestConverter.convertToSplitGroups(deliveryProducts);
        AppClientInfo appClientInfo = new AppClientInfo();
        appClientInfo.setAppName("asdp");
        appClientInfo.setInvokeInterfaceName("");
        appClientInfo.setInvokeMethodName("");
        DeliveryResult<OrderSplitResultTO> orderSplitResultTODeliveryResult = BizServiceLocator.getLogisticsFeeService().splitAllDeliveryOrders(orderSplitQueryTO, appClientInfo);
        if (null == orderSplitResultTODeliveryResult || !orderSplitResultTODeliveryResult.isSuccess()) {
            return;
        }
        OrderSplitResultTO orderSplitResultTO = orderSplitResultTODeliveryResult.getResult();
        invalidItems(orderSplitResultTO.getUnAvailableList(), session);

        Map<String, String> uniqueKeyToOrderId = Maps.newHashMap();
        Map<String, AsdpItemInfo> itemUniqueKeyToItemInfoMap = Maps.newHashMap();
        Map<String, Set<String>> orderIdToUniqueSet = Maps.newHashMap();
        // 原包裹id到物流商品的关联关系map
        Map<String, DeliveryProduct> productMap = Maps.newHashMap();
        for (DeliveryProduct deliveryProduct : deliveryProducts) {
            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            productMap.put(deliveryPackage.getPackageId(), deliveryProduct);
            for (AsdpItemInfo itemInfo : deliveryPackage.getItemInfos()) {
                itemUniqueKeyToItemInfoMap.put(itemInfo.getUniqueKey(), itemInfo);
                uniqueKeyToOrderId.put(itemInfo.getUniqueKey(), deliveryPackage.getPackageId());
                orderIdToUniqueSet.computeIfAbsent(deliveryPackage.getPackageId(), key -> Sets.newHashSet()).add(itemInfo.getUniqueKey());
            }
        }

        List<DeliveryProduct> newDeliveryProducts = Lists.newArrayList();
        PackageIdFactory packageIdFactory = new PackageIdFactory();
        List<ItemSplitGroup> orderSplitItems = orderSplitResultTO.getOrderSplitItems();
        for (ItemSplitGroup orderSplitItem : orderSplitItems) {
            List<ItemPackageTO> itemPackages = orderSplitItem.getItemPackages();
            if (CollectionUtils.isEmpty(itemPackages)) {
                continue;
            }
            Set<String> uniqueKeys = itemPackages.stream().map(ItemPackageTO::getItemDesc).map(ItemDesc::getUniqueKey).collect(Collectors.toSet());
            String orderId = uniqueKeys.stream().map(uniqueKeyToOrderId::get).filter(Objects::nonNull).findAny().orElse(null);
            if (StringUtils.isBlank(orderId)) {
                continue;
            }
            DeliveryProduct deliveryProduct = productMap.get(orderId);
            if (null == deliveryProduct) {
                continue;
            }

            //构建wdk时间片协议
            DeliveryProtocolClause wdkProtocol = null;
            String wdkFulfillProductGroup = MapUtils.getString(orderSplitItem.getFeatures(), AdapterConstant.WDK_FULFIL_PRODUCT_GROUP);
            if (StringUtils.isNotBlank(wdkFulfillProductGroup)) {
                Map<String, String> extend = Maps.newHashMap();
                extend.put(AdapterConstant.WDK_FULFIL_PRODUCT_GROUP, wdkFulfillProductGroup);
                wdkProtocol = new DeliveryProtocolClause();
                wdkProtocol.setProtocolType(SerializeConstant.PROTOCOL_TYPE_WDK);
                wdkProtocol.setTags(extend);
            }

            //构建sdp时间片协议(新猫半链路新增)
            DeliveryProtocolClause sdpTimeSliceProtocol = null;
            String sdpFulfillProductGroup = MapUtils.getString(orderSplitItem.getFeatures(),
                AdapterConstant.SDP_FULFIL_PRODUCT_GROUP);
            if (StringUtils.isNotBlank(sdpFulfillProductGroup)) {
                Map<String, String> extend = Maps.newHashMap();
                extend.put(AdapterConstant.SDP_FULFIL_PRODUCT_GROUP, sdpFulfillProductGroup);
                sdpTimeSliceProtocol = new DeliveryProtocolClause();
                sdpTimeSliceProtocol.setProtocolType(SerializeConstant.PROTOCOL_TYPE_SDP_TIME_SLICE);
                sdpTimeSliceProtocol.setTags(extend);
            }

            DeliveryPackage deliveryPackage = deliveryProduct.getDeliveryPackage();
            if (deliveryPackage.getItemInfos().size() == uniqueKeys.size()) {
                List<DeliveryProtocolClause> expectProtocols = deliveryProduct.getExpectProtocols();
                if (wdkProtocol != null) {
                    expectProtocols.add(wdkProtocol);
                }
                if (sdpTimeSliceProtocol != null) {
                    expectProtocols.add(sdpTimeSliceProtocol);
                }
                continue;
            }
            List<AsdpItemInfo> newItemInfos = Lists.newArrayList();
            session.getDeliveryProducts().remove(deliveryProduct);

            DeliveryProduct newProduct = deliveryProduct.clone(packageIdFactory.getNextPackageId(deliveryPackage.getPackageId()));
            for (String uniqueKey : uniqueKeys) {
                AsdpItemInfo sourceAsdpItemInfo = itemUniqueKeyToItemInfoMap.remove(uniqueKey);
                if (null != sourceAsdpItemInfo) {
                    newItemInfos.add(sourceAsdpItemInfo);
                }
            }
            if (null != newProduct && CollectionUtils.isNotEmpty(newItemInfos)) {
                List<DeliveryProtocolClause> expectProtocols = newProduct.getExpectProtocols();
                if (wdkProtocol != null) {
                    expectProtocols.add(wdkProtocol);
                }
                if (sdpTimeSliceProtocol != null) {
                    expectProtocols.add(sdpTimeSliceProtocol);
                }
                newProduct.getDeliveryPackage().getItemInfos().clear();
                newProduct.getDeliveryPackage().getItemInfos().addAll(newItemInfos);
                newDeliveryProducts.add(newProduct);
            }
        }
        session.getDeliveryProducts().addAll(newDeliveryProducts);
    }


    private void invalidItems(Map<ItemPackageTO, ServiceErrorCode> unavailableItems, DeliverySession session) {
        if (MapUtils.isEmpty(unavailableItems)) {
            return;
        }
        List<InvalidItem> invalidItems = Lists.newArrayList();
        for (Map.Entry<ItemPackageTO, ServiceErrorCode> entry : unavailableItems.entrySet()) {
            ItemPackageTO itemPackageTO = entry.getKey();
            ItemDesc itemDesc = itemPackageTO.getItemDesc();
            InvalidItem invalidItem = new InvalidItem();
            invalidItem.setItemUniqueKey(itemDesc.getUniqueKey());
            invalidItem.setItemId(itemDesc.getItemId());
            invalidItem.setSkuId(itemDesc.getSkuId());
            ServiceErrorCode value = entry.getValue();
            invalidItem.setUndeliverableReasonMessage(value.getMessage());
            invalidItem.setUndeliverableReasonCode(value.getCode());
            invalidItems.add(invalidItem);
        }
        session.invalidItems(invalidItems);
    }

    static class PackageIdFactory {

        Map<String, Integer> orderCntMap = Maps.newHashMap();

        String getNextPackageId(String packageId) {
            Integer count = orderCntMap.compute(packageId, (key, oldValue) -> {
                if (null == oldValue) {
                    return 0;
                }
                return oldValue + 1;
            });
            return packageId + "_" + count;
        }

    }


}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.ascp.sdp2.sdk.model.base.logisticsnode.ReceiverAddress;
import com.alibaba.asdp.core.diamond.SplitConfig;
import com.alibaba.asdp.sdk.BizServiceLocator;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.asdp.sdk.service.fee.FeeTemplate;
import com.alibaba.asdp.sdk.service.fee.TemplateRequest;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.taobao.delivery.common.constant.DeliveryConstant;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.collections4.MapUtils;

import java.util.Iterator;
import java.util.List;
import java.util.Map;

/**
 * 按照配置的运送方式拆单
 *
 * 这里同时还会处理adp的区域限运
 *
 * @author jiajun.njj 2020/7/29 8:31 下午
 */
public class DeliveryTypeSplitter extends AbsDeliveryPackageSplitter {

    @Override
    public List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
        ReceiverAddress originalAddress = deliveryPackage.getOriginalAddress();
        Long divisionId = (originalAddress.getDivisionId() == null || originalAddress.getDivisionId() <= 0) ? DeliveryConstant.AREA_ID_CHINA : originalAddress.getDivisionId();

        List<AsdpItemInfo> itemInfos = Lists.newArrayList(deliveryPackage.getItemInfos());
        Iterator<AsdpItemInfo> iterator = itemInfos.iterator();
        Map<Long, List<AsdpItemInfo>> lgTypeItemGroup = Maps.newHashMap();
        while (iterator.hasNext()) {
            AsdpItemInfo itemInfo = iterator.next();
            AsdpEcomItem ecomItem = itemInfo.getEcomItem();
            TemplateRequest templateRequest = TemplateRequest.builder()
                    .areaId(divisionId)
                    .templateId(ecomItem.getTemplateId())
                    .userId(ecomItem.getSeller().getUserId())
                    .build();
            FeeTemplate feeTemplate = BizServiceLocator.getLogisticsFeeService().queryTemplate(templateRequest);
            // 这里是有顺序的，依赖配置的顺序
            for (Long splitLgType : SplitConfig.getInstance().getSplitLgTypes()) {
                if (feeTemplate.getServiceTypes().contains(splitLgType)) {
                    List<AsdpItemInfo> asdpItemInfos = lgTypeItemGroup.computeIfAbsent(splitLgType, key -> Lists.newArrayList());
                    asdpItemInfos.add(itemInfo);
                    iterator.remove();
                    break;
                }
            }
        }
        List<List<AsdpItemInfo>> groups = Lists.newArrayList();
        // 这是按照指定运送方式分组的商品
        if (MapUtils.isNotEmpty(lgTypeItemGroup)) {
            groups.addAll(Lists.newArrayList(lgTypeItemGroup.values()));
        }
        // 这是按照指定运送方式拆分后剩下的商品
        if (CollectionUtils.isNotEmpty(itemInfos)) {
            groups.add(itemInfos);
        }
        return groups;

    }
}

package com.alibaba.asdp.core.stage.split.splitter;

import com.alibaba.asdp.core.util.ItemUtils;
import com.alibaba.asdp.sdk.model.item.AsdpEcomItem;
import com.alibaba.asdp.sdk.model.item.AsdpItemInfo;
import com.alibaba.asdp.sdk.model.parcel.DeliveryPackage;
import com.alibaba.delivery.logistics.utils.ShipTimeUtils;
import com.google.common.collect.Lists;
import org.apache.commons.collections4.CollectionUtils;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.math.NumberUtils;
import org.apache.commons.lang3.tuple.Pair;

import java.time.LocalDateTime;
import java.util.*;
import java.util.stream.Collectors;

/**
 * @author LinYuanSheng
 * @date 2025/3/6
 */
public class ShipTimeDiffSplit extends AbsDeliveryPackageSplitter {

	private static final String SJC_FLA = "sjcFla";

	private static final String SHIP_TIME = "shipTime";

	/**
	 * 根据发货时效拆单标
	 */
	private static final int TIMING_SPLIT_TAG = 793665;

	private static final String DONT_NEED_SPLIT = "DONT_NEED_SPLIT";

	@Override
	List<List<AsdpItemInfo>> doSplit(DeliveryPackage deliveryPackage) {
		ArrayList<List<AsdpItemInfo>> result = Lists.newArrayList();
		final List<AsdpItemInfo> asdpItemInfos = Optional.ofNullable(deliveryPackage)
				.map(DeliveryPackage::getItemInfos)
				.orElse(null);
		if (CollectionUtils.isEmpty(asdpItemInfos)) {
			return result;
		}
		try {

			LocalDateTime now = LocalDateTime.now();
			final Map<String, List<AsdpItemInfo>> splitGroup = asdpItemInfos.stream().collect(Collectors.groupingBy(item -> {

				if (item == null || item.getEcomItem() == null) {
					return DONT_NEED_SPLIT;
				}

				final AsdpEcomItem ecomItem = item.getEcomItem();
				final Set<Integer> itemTags = ecomItem.getItemTags();
				if (CollectionUtils.isEmpty(itemTags)) {
					return DONT_NEED_SPLIT;
				}
				if (!itemTags.contains(TIMING_SPLIT_TAG)) {
					return DONT_NEED_SPLIT;
				}

				//如果是一盘货并且是商家仓
				if (ItemUtils.isOneStockOrder(item) && ItemUtils.isSellerStore(item)) {

					String key;
					final String ipmFla = ItemUtils.fetchSellerShipTimeOfInv(item);
					if (StringUtils.isNotBlank(ipmFla)) {
						key = generateKey(ipmFla, now, SJC_FLA);
					} else {
						//获取现货时间
						String shipTime = ItemUtils.fetchShipTimeOfIc(item);
						key = generateKey(shipTime, now, SHIP_TIME);
					}
					if (StringUtils.isNotBlank(key)) {
						return key;
					}

				}
				return DONT_NEED_SPLIT;
			}));

			result.addAll(splitGroup.values());
		} catch (Throwable ignore) {
			//拆单失败先不管了,原封不动返回
			result.add(asdpItemInfos);
			return result;
		}
		return result;
	}

	private String generateKey(String shipTime, LocalDateTime now, String prefix) {
		if (StringUtils.isBlank(shipTime)) {
			return null;
		}
		final Pair<String, String> structShipTime = ShipTimeUtils.getStructShipTime(shipTime);
		if (structShipTime == null || structShipTime.getLeft() == null || structShipTime.getRight() == null) {
			return null;
		}
		if (ShipTimeUtils.isRelativeTime(structShipTime.getLeft())) {
			if (NumberUtils.isCreatable(structShipTime.getRight())) {
				final LocalDateTime shipTimeDateTime = now.plusDays(Long.parseLong(structShipTime.getRight()));
				final String shipTimeStr = shipTimeDateTime.toLocalDate().toString();
				return prefix + "_" + shipTimeStr;
			}
		} else if (ShipTimeUtils.isAbsoluteTime(structShipTime.getLeft())) {
			if (StringUtils.isNotBlank(structShipTime.getRight())) {
				return prefix + "_" + structShipTime.getRight();
			}
		}
		return null;
	}
}

